#include <openssl/evp.h>

static PyObject *encrypt(PyObject *self, PyObject *args) {
    Py_buffer key, nonce, plaintext, aad;
    int has_aad = 1;
    if (!PyArg_ParseTuple(args, "y*y*y*y*", &key, &nonce, &plaintext, &aad)) {
        PyErr_Clear();
        if (!PyArg_ParseTuple(args, "y*y*y*", &key, &nonce, &plaintext))
            return NULL;
        has_aad = 0;
        aad.buf = NULL;
        aad.len = 0;
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&plaintext);
        if (has_aad) PyBuffer_Release(&aad);
        return PyErr_NoMemory();
    }

    int ok = 1;
    int outlen = 0, tmplen = 0;
    PyObject *ct_obj = NULL;
    PyObject *tag_obj = NULL;
    unsigned char tag[16];

    if (EVP_EncryptInit_ex(ctx, EVP_chacha20_poly1305(), NULL, NULL, NULL) != 1) ok = 0;
    if (ok && EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, (int)nonce.len, NULL) != 1) ok = 0;
    if (ok && EVP_EncryptInit_ex(ctx, NULL, NULL, key.buf, nonce.buf) != 1) ok = 0;

    if (ok && aad.len > 0) {
        if (EVP_EncryptUpdate(ctx, NULL, &outlen, aad.buf, (int)aad.len) != 1) ok = 0;
    }

    if (ok) {
        ct_obj = PyBytes_FromStringAndSize(NULL, plaintext.len);
        if (!ct_obj) ok = 0;
    }
    if (ok) {
        unsigned char *ct = (unsigned char *)PyBytes_AS_STRING(ct_obj);
        if (EVP_EncryptUpdate(ctx, ct, &outlen, plaintext.buf, (int)plaintext.len) != 1) ok = 0;
        else if (EVP_EncryptFinal_ex(ctx, ct + outlen, &tmplen) != 1) ok = 0;
        else if (outlen + tmplen != (int)plaintext.len) {
            /* resize if needed */
            if (_PyBytes_Resize(&ct_obj, outlen + tmplen) < 0) ok = 0;
        }
    }
    if (ok) {
        if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag) != 1) ok = 0;
        else tag_obj = PyBytes_FromStringAndSize((char *)tag, 16);
    }

    EVP_CIPHER_CTX_free(ctx);
    PyBuffer_Release(&key);
    PyBuffer_Release(&nonce);
    PyBuffer_Release(&plaintext);
    if (has_aad) PyBuffer_Release(&aad);

    if (!ok || !tag_obj) {
        Py_XDECREF(ct_obj);
        Py_XDECREF(tag_obj);
        if (!PyErr_Occurred())
            PyErr_SetString(PyExc_RuntimeError, "ChaCha20-Poly1305 encryption failed");
        return NULL;
    }
    return Py_BuildValue("(NN)", ct_obj, tag_obj);
}

static PyMethodDef methods[] = {
    {"encrypt", encrypt, METH_VARARGS, "ChaCha20-Poly1305 encrypt"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "chacha_ext", NULL, -1, methods
};

PyMODINIT_FUNC PyInit_chacha_ext(void) {
    return PyModule_Create(&moduledef);
}
