#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/evp.h>

static double now() {
    struct timespec t;
    clock_gettime(CLOCK_MONOTONIC, &t);
    return t.tv_sec + t.tv_nsec/1e9;
}

int main() {
    size_t n = 40UL*1024*1024;
    unsigned char *a = malloc(n+64);
    unsigned char *b = malloc(n+64);
    if (!a || !b) return 1;
    memset(a, 1, n);
    volatile unsigned long long sink = 0;

    int iters = 10;
    double t0 = now();
    for (int i = 0; i < iters; i++) {
        memcpy(b, a, n);
        sink += b[i];
    }
    double dt = now() - t0;
    printf("memcpy 40MB x%d: %.3f ms avg, bandwidth %.2f GB/s\n", iters, dt/iters*1000, (n/(dt/iters))/1e9);

    t0 = now();
    for (int i = 0; i < iters; i++) {
        memset(b, i+1, n);
        sink += b[i];
    }
    dt = now() - t0;
    printf("memset 40MB x%d: %.3f ms avg, bandwidth %.2f GB/s\n", iters, dt/iters*1000, (n/(dt/iters))/1e9);

    t0 = now();
    for (int i = 0; i < iters; i++) {
        for (size_t j = 0; j < n; j += 8) {
            *(unsigned long long*)(b+j) = *(unsigned long long*)(a+j) ^ 0x123456789abcdefULL;
        }
        sink += b[0];
    }
    dt = now() - t0;
    printf("xor64 40MB x%d: %.3f ms avg, pt-throughput %.2f GB/s\n", iters, dt/iters*1000, (n/(dt/iters))/1e9);

    // OpenSSL EVP chacha20-poly1305
    unsigned char key[32] = {0};
    unsigned char nonce[12] = {0};
    unsigned char tag[16];
    unsigned char aad[32] = {1};
    for (int i = 0; i < 32; i++) key[i] = i;

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    // warmup
    {
        int outlen=0, tmplen=0;
        EVP_EncryptInit_ex(ctx, EVP_chacha20_poly1305(), NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
        EVP_EncryptUpdate(ctx, b, &outlen, a, (int)n);
        EVP_EncryptFinal_ex(ctx, b+outlen, &tmplen);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
    }
    t0 = now();
    for (int i = 0; i < iters; i++) {
        int outlen=0, tmplen=0;
        EVP_EncryptInit_ex(ctx, EVP_chacha20_poly1305(), NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
        EVP_EncryptUpdate(ctx, b, &outlen, a, (int)n);
        EVP_EncryptFinal_ex(ctx, b+outlen, &tmplen);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
        sink += b[i] + tag[0];
    }
    dt = now() - t0;
    printf("openssl chacha20-poly1305 40MB x%d: %.3f ms avg, throughput %.2f MB/s\n", iters, dt/iters*1000, (n/(dt/iters))/1e6);

    // reuse ctx with reset
    t0 = now();
    for (int i = 0; i < iters; i++) {
        int outlen=0, tmplen=0;
        EVP_CIPHER_CTX_reset(ctx);
        EVP_EncryptInit_ex(ctx, EVP_chacha20_poly1305(), NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
        EVP_EncryptUpdate(ctx, b, &outlen, a, (int)n);
        EVP_EncryptFinal_ex(ctx, b+outlen, &tmplen);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
        sink += b[i];
    }
    dt = now() - t0;
    printf("openssl reset 40MB x%d: %.3f ms avg\n", iters, dt/iters*1000);

    printf("sink %llu\n", sink);
    return 0;
}
