#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>
#include <openssl/evp.h>

static double now() {
    struct timespec t;
    clock_gettime(CLOCK_MONOTONIC, &t);
    return t.tv_sec + t.tv_nsec/1e9;
}

static volatile uint64_t sink;

void *worker_copy(void *arg) {
    unsigned char **p = arg;
    unsigned char *a = p[0], *b = p[1];
    size_t n = 40UL*1024*1024;
    uint64_t s = 0;
    for (int i = 0; i < 4; i++) {
        memcpy(b, a, n);
        s += b[i*1024];
    }
    sink += s;
    return NULL;
}

typedef struct {
    unsigned char *in, *out;
    size_t n;
    unsigned char key[32];
    unsigned char nonce[12];
    unsigned char aad[32];
    int iters;
} Job;

void *worker_enc(void *arg) {
    Job *j = arg;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    unsigned char tag[16];
    uint64_t s = 0;
    for (int i = 0; i < j->iters; i++) {
        int outlen=0, tmplen=0;
        EVP_EncryptInit_ex(ctx, EVP_chacha20_poly1305(), NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, j->key, j->nonce);
        EVP_EncryptUpdate(ctx, NULL, &outlen, j->aad, 32);
        EVP_EncryptUpdate(ctx, j->out, &outlen, j->in, (int)j->n);
        EVP_EncryptFinal_ex(ctx, j->out+outlen, &tmplen);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
        s += j->out[0] + tag[0];
    }
    sink += s;
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

int main() {
    size_t n = 40UL*1024*1024;
    unsigned char *a = aligned_alloc(64, n);
    unsigned char *b = aligned_alloc(64, n);
    memset(a, 1, n);
    memset(b, 2, n);

    /* force touch */
    double t0 = now();
    for (int i = 0; i < 8; i++) {
        memcpy(b, a, n);
        sink += b[(i*4096) & (n-1)];
    }
    double dt = now()-t0;
    printf("memcpy single 40MB x8: %.3f ms avg  (%.2f GB/s copied)\n", dt/8*1000, (n/(dt/8))/1e9);

    /* streaming xor that reads and writes, not optimizable */
    t0 = now();
    int iters = 8;
    for (int i = 0; i < iters; i++) {
        uint64_t *dst = (uint64_t*)b;
        uint64_t *src = (uint64_t*)a;
        size_t words = n/8;
        uint64_t k = (uint64_t)i * 0x9e3779b97f4a7c15ULL;
        for (size_t j = 0; j < words; j++) dst[j] = src[j] ^ k;
        sink += b[0];
    }
    dt = now()-t0;
    printf("xor single 40MB x%d: %.3f ms avg (%.2f GB/s pt)\n", iters, dt/iters*1000, (n/(dt/iters))/1e9);

    /* parallel memcpy 6 threads, each 40MB */
    int nth = 6;
    pthread_t th[8];
    unsigned char *ins[8], *outs[8];
    unsigned char *args[8][2];
    for (int i = 0; i < nth; i++) {
        ins[i] = aligned_alloc(64, n);
        outs[i] = aligned_alloc(64, n);
        memset(ins[i], i+1, n);
        args[i][0] = ins[i];
        args[i][1] = outs[i];
    }
    t0 = now();
    for (int i = 0; i < nth; i++) pthread_create(&th[i], NULL, worker_copy, args[i]);
    for (int i = 0; i < nth; i++) pthread_join(th[i], NULL);
    dt = now()-t0;
    printf("memcpy %d threads x4 x40MB: %.3f ms wall for 4 rounds, per-round %.3f ms, agg %.2f GB/s\n",
           nth, dt*1000, dt/4*1000, (n*nth/(dt/4))/1e9);

    /* parallel encrypt, split 40MB into nth chunks conceptually: each thread encrypts n/nth */
    size_t chunk = n / nth;
    Job jobs[8];
    for (int i = 0; i < nth; i++) {
        memset(&jobs[i], 0, sizeof(Job));
        jobs[i].in = ins[i];
        jobs[i].out = outs[i];
        jobs[i].n = chunk;
        jobs[i].iters = 4;
        jobs[i].key[0] = i;
        jobs[i].nonce[0] = i;
    }
    /* warmup */
    for (int i = 0; i < nth; i++) { jobs[i].iters = 1; }
