cat > build/chacha_bench.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <immintrin.h>

static double now() {
    struct timespec t; clock_gettime(CLOCK_MONOTONIC, &t);
    return t.tv_sec + t.tv_nsec*1e-9;
}

static inline __m256i rotl32_avx(__m256i x, int n) {
    return _mm256_or_si256(_mm256_slli_epi32(x, n), _mm256_srli_epi32(x, 32-n));
}

/* quarter round on 8 parallel blocks, columns of the state are in s0..s15 where
   each si holds word i of 8 blocks. */
static inline void QR(__m256i *a, __m256i *b, __m256i *c, __m256i *d) {
    *a = _mm256_add_epi32(*a, *b);
    *d = _mm256_xor_si256(*d, *a);
    *d = rotl32_avx(*d, 16);
    *c = _mm256_add_epi32(*c, *d);
    *b = _mm256_xor_si256(*b, *c);
    *b = rotl32_avx(*b, 12);
    *a = _mm256_add_epi32(*a, *b);
    *d = _mm256_xor_si256(*d, *a);
    *d = rotl32_avx(*d, 8);
    *c = _mm256_add_epi32(*c, *d);
    *b = _mm256_xor_si256(*b, *c);
    *b = rotl32_avx(*b, 7);
}

/* Generate 8 blocks (512 bytes) of keystream starting at counter, XOR into dst from src.
   key is 8 little-endian words, nonce is 3 little-endian words. */
static void chacha_xor8(const uint32_t key[8], const uint32_t nonce[3], uint32_t counter,
                        const uint8_t *src, uint8_t *dst) {
    const __m256i c0 = _mm256_set1_epi32(0x61707865);
    const __m256i c1 = _mm256_set1_epi32(0x3320646e);
    const __m256i c2 = _mm256_set1_epi32(0x79622d32);
    const __m256i c3 = _mm256_set1_epi32(0x6b206574);
    __m256i k0 = _mm256_set1_epi32(key[0]);
    __m256i k1 = _mm256_set1_epi32(key[1]);
    __m256i k2 = _mm256_set1_epi32(key[2]);
    __m256i k3 = _mm256_set1_epi32(key[3]);
    __m256i k4 = _mm256_set1_epi32(key[4]);
    __m256i k5 = _mm256_set1_epi32(key[5]);
    __m256i k6 = _mm256_set1_epi32(key[6]);
    __m256i k7 = _mm256_set1_epi32(key[7]);
    __m256i n0 = _mm256_set1_epi32(nonce[0]);
    __m256i n1 = _mm256_set1_epi32(nonce[1]);
    __m256i n2 = _mm256_set1_epi32(nonce[2]);
    /* counters for 8 blocks: counter+0 .. counter+7, laid out across the 256-bit lane groups.
       _mm256_set_epi32 sets from highest element. We want element i = counter+i. */
    __m256i ctr = _mm256_set_epi32(counter+7, counter+6, counter+5, counter+4,
                                   counter+3, counter+2, counter+1, counter+0);

    __m256i s0=c0,s1=c1,s2=c2,s3=c3,s4=k0,s5=k1,s6=k2,s7=k3,s8=k4,s9=k5,s10=k6,s11=k7,s12=ctr,s13=n0,s14=n1,s15=n2;

    for (int i = 0; i < 10; i++) {
        /* column rounds */
        QR(&s0,&s4,&s8,&s12);
        QR(&s1,&s5,&s9,&s13);
        QR(&s2,&s6,&s10,&s14);
        QR(&s3,&s7,&s11,&s15);
        /* diagonal rounds */
        QR(&s0,&s5,&s10,&s15);
        QR(&s1,&s6,&s11,&s12);
        QR(&s2,&s7,&s8,&s13);
        QR(&s3,&s4,&s9,&s14);
    }
    s0 = _mm256_add_epi32(s0, c0);
    s1 = _mm256_add_epi32(s1, c1);
    s2 = _mm256_add_epi32(s2, c2);
    s3 = _mm256_add_epi32(s3, c3);
    s4 = _mm256_add_epi32(s4, k0);
    s5 = _mm256_add_epi32(s5, k1);
    s6 = _mm256_add_epi32(s6, k2);
    s7 = _mm256_add_epi32(s7, k3);
    s8 = _mm256_add_epi32(s8, k4);
    s9 = _mm256_add_epi32(s9, k5);
    s10 = _mm256_add_epi32(s10, k6);
    s11 = _mm256_add_epi32(s11, k7);
    s12 = _mm256_add_epi32(s12, ctr);
    s13 = _mm256_add_epi32(s13, n0);
    s14 = _mm256_add_epi32(s14, n1);
    s15 = _mm256_add_epi32(s15, n2);

    /* Transpose 8 blocks of 16 words into block-major order and XOR.
       Each block is 64 bytes = 16 uint32. We'll store transposed via scalar extract for correctness first,
       then optimize. For benchmark of compute, store interleaved then fix — but we want real XOR bandwidth.
       Use a straightforward extract. */
    uint32_t tmp[8*16];
    _mm256_storeu_si256((__m256i*)(tmp+0), s0);
    _mm256_storeu_si256((__m256i*)(tmp+8), s1);
    _mm256_storeu_si256((__m256i*)(tmp+16), s2);
    _mm256_storeu_si256((__m256i*)(tmp+24), s3);
    _mm256_storeu_si256((__m256i*)(tmp+32), s4);
    _mm256_storeu_si256((__m256i*)(tmp+40), s5);
    _mm256_storeu_si256((__m256i*)(tmp+48), s6);
    _mm256_storeu_si256((__m256i*)(tmp+56), s7);
    _mm256_storeu_si256((__m256i*)(tmp+64), s8);
    _mm256_storeu_si256((__m256i*)(tmp+72), s9);
    _mm256_storeu_si256((__m256i*)(tmp+80), s10);
    _mm256_storeu_si256((__m256i*)(tmp+88), s11);
    _mm256_storeu_si256((__m256i*)(tmp+96), s12);
    _mm256_storeu_si256((__m256i*)(tmp+104), s13);
    _mm256_storeu_si256((__m256i*)(tmp+112), s14);
    _mm256_storeu_si256((__m256i*)(tmp+120), s15);

    /* tmp layout: word w of block b is at tmp[w*8 + b] */
    for (int b = 0; b < 8; b++) {
        uint32_t block[16];
        for (int w = 0; w < 16; w++) block[w] = tmp[w*8 + b];
        const uint32_t *sp = (const uint32_t*)(src + b*64);
        uint32_t *dp = (uint32_t*)(dst + b*64);
        for (int w = 0; w < 16; w++) dp[w] = sp[w] ^ block[w];
    }
}

static volatile uint64_t sink;

int main() {
    size_t n = 40UL<<20;
    uint8_t *src = aligned_alloc(64, n);
    uint8_t *dst = aligned_alloc(64, n);
    memset(src, 0x5a, n);
    uint32_t key[8] = {1,2,3,4,5,6,7,8};
    uint32_t nonce[3] = {9,10,11};

    /* warmup */
    for (size_t off = 0; off < n; off += 512) {
        chacha_xor8(key, nonce, (uint32_t)(off/64), src+off, dst+off);
    }
    sink += dst[0];

    int iters = 3;
    double t0 = now();
    for (int i = 0; i < iters; i++) {
        for (size_t off = 0; off < n; off += 512) {
            chacha_xor8(key, nonce, (uint32_t)(off/64), src+off, dst+off);
        }
        sink += dst[i];
    }
    double dt = now()-t0;
    printf("avx2 chacha8 40MB x%d: %.3f ms avg, throughput %.1f MB/s\n",
           iters, dt/iters*1000, (n/(dt/iters))/1e6);
    printf("sink %llu dst[0]=%u\n", (unsigned long long)sink, dst[0]);
    return 0;
}
EOF
clang -O3 -mavx2 -o build/chacha_bench build/chacha_bench.c && ./build/chacha_bench"}

