#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <immintrin.h>

static double now() {
    struct timespec t; clock_gettime(CLOCK_MONOTONIC, &t);
    return t.tv_sec + t.tv_nsec*1e-9;
}

/* 4-way AVX2 ChaCha20. Each ymm holds one word across 4 blocks? 
   Actually use 128-bit x4 packed into ymm: word i of 4 blocks in one ymm? 
   Simpler: 4 independent blocks, each block's 16 words don't fit.
   Standard approach: 4 blocks, each column-word is a 128-bit lane pair.
   We'll do 4 blocks using SSE-style but in ymm by processing 2x2.

   Layout: process 4 blocks. State word j of the 4 blocks is one __m128i x4 stored as __m256i? 
   4 x 32-bit = 128 bits. So use __m128i. 16 registers of xmm fit exactly the state, no spill of state.
   XMM has 16 regs. We need a temp for rotates -> spill one word. Still much less pressure than 8-way.
*/

static inline __m128i rotl(__m128i x, int n) {
    return _mm_or_si128(_mm_slli_epi32(x, n), _mm_srli_epi32(x, 32-n));
}
static inline void QR(__m128i *a, __m128i *b, __m128i *c, __m128i *d) {
    *a = _mm_add_epi32(*a, *b);
    *d = _mm_xor_si128(*d, *a); *d = rotl(*d, 16);
    *c = _mm_add_epi32(*c, *d);
    *b = _mm_xor_si128(*b, *c); *b = rotl(*b, 12);
    *a = _mm_add_epi32(*a, *b);
    *d = _mm_xor_si128(*d, *a); *d = rotl(*d, 8);
    *c = _mm_add_epi32(*c, *d);
    *b = _mm_xor_si128(*b, *c); *b = rotl(*b, 7);
}

/* 4 blocks = 256 bytes */
static void chacha4(const uint32_t key[8], const uint32_t nonce[3], uint32_t counter,
                    const uint8_t *src, uint8_t *dst) {
    __m128i c0 = _mm_set1_epi32(0x61707865);
    __m128i c1 = _mm_set1_epi32(0x3320646e);
    __m128i c2 = _mm_set1_epi32(0x79622d32);
    __m128i c3 = _mm_set1_epi32(0x6b206574);
    __m128i k0 = _mm_set1_epi32(key[0]);
    __m128i k1 = _mm_set1_epi32(key[1]);
    __m128i k2 = _mm_set1_epi32(key[2]);
    __m128i k3 = _mm_set1_epi32(key[3]);
    __m128i k4 = _mm_set1_epi32(key[4]);
    __m128i k5 = _mm_set1_epi32(key[5]);
    __m128i k6 = _mm_set1_epi32(key[6]);
    __m128i k7 = _mm_set1_epi32(key[7]);
    __m128i n0 = _mm_set1_epi32(nonce[0]);
    __m128i n1 = _mm_set1_epi32(nonce[1]);
    __m128i n2 = _mm_set1_epi32(nonce[2]);
    __m128i ctr = _mm_set_epi32(counter+3, counter+2, counter+1, counter+0);

    __m128i s0=c0,s1=c1,s2=c2,s3=c3,s4=k0,s5=k1,s6=k2,s7=k3,s8=k4,s9=k5,s10=k6,s11=k7,s12=ctr,s13=n0,s14=n1,s15=n2;
    for (int i = 0; i < 10; i++) {
        QR(&s0,&s4,&s8,&s12);
        QR(&s1,&s5,&s9,&s13);
        QR(&s2,&s6,&s10,&s14);
        QR(&s3,&s7,&s11,&s15);
        QR(&s0,&s5,&s10,&s15);
        QR(&s1,&s6,&s11,&s12);
        QR(&s2,&s7,&s8,&s13);
        QR(&s3,&s4,&s9,&s14);
    }
    s0=_mm_add_epi32(s0,c0); s1=_mm_add_epi32(s1,c1); s2=_mm_add_epi32(s2,c2); s3=_mm_add_epi32(s3,c3);
    s4=_mm_add_epi32(s4,k0); s5=_mm_add_epi32(s5,k1); s6=_mm_add_epi32(s6,k2); s7=_mm_add_epi32(s7,k3);
    s8=_mm_add_epi32(s8,k4); s9=_mm_add_epi32(s9,k5); s10=_mm_add_epi32(s10,k6); s11=_mm_add_epi32(s11,k7);
    s12=_mm_add_epi32(s12,ctr); s13=_mm_add_epi32(s13,n0); s14=_mm_add_epi32(s14,n1); s15=_mm_add_epi32(s15,n2);

    /* transpose 4x4 words groups and xor. Store word-major then transpose in 32-bit. */
    __m128i w[16] = {s0,s1,s2,s3,s4,s5,s6,s7,s8,s9,s10,s11,s12,s13,s14,s15};
