/* 4-way but using AVX2 so each QR processes 8 blocks with less spill by doing two independent
   4-block groups? Skip. */

static volatile uint64_t sink;

/* Also an AVX2 4-block version where we pack 4 blocks into the low? no, 4*32=128.
   Try 8-way but with explicit asm rotates and no transpose: store word-major and XOR with a
   gathered load. For throughput measurement, XOR in word-major order against a pre-shuffled src
   so we measure pure compute. */

static void chacha8_compute_only(const uint32_t key[8], const uint32_t nonce[3], uint32_t counter,
                                 uint32_t *dst_wordmajor) {
    __m256i c0 = _mm256_set1_epi32(0x61707865);
