    __m256i c2 = _mm256_set1_epi32(0x79622d32);
    __m256i c3 = _mm256_set1_epi32(0x6b206574);
    __m256i k0 = _mm256_set1_epi32(key[0]);
    __m256i k1 = _mm256_set1_epi32(key[1]);
    __m256i k2 = _mm256_set1_epi32(key[2]);
    __m256i k3 = _mm256_set1_epi32(key[3]);
    __m256i k4 = _mm256_set1_epi32(key[4]);
    __m256i k5 = _mm256_set1_epi32(key[5]);
    __m256i k6 = _mm256_set1_epi32(key[6]);
    __m256i k7 = _mm256_set1_epi32(key[7]);
    __m256i n0 = _mm256_set1_epi32(nonce[0]);
    __m256i n1 = _mm256_set1_epi32(nonce[1]);
    __m256i n2 = _mm256_set1_epi32(nonce[2]);
    __m256i ctr = _mm256_set_epi32(counter+7,counter+6,counter+5,counter+4,counter+3,counter+2,counter+1,counter);

    __m256i s0=c0,s1=c1,s2=c2,s3=c3,s4=k0,s5=k1,s6=k2,s7=k3,s8=k4,s9=k5,s10=k6,s11=k7,s12=ctr,s13=n0,s14=n1,s15=n2;
    for (int i = 0; i < 10; i++) {
        #define QR8(a,b,c,d) do { \
            a = _mm256_add_epi32(a, b); \
            d = _mm256_xor_si256(d, a); \
            d = _mm256_or_si256(_mm256_slli_epi32(d,16), _mm256_srli_epi32(d,16)); \
            c = _mm256_add_epi32(c, d); \
            b = _mm256_xor_si256(b, c); \
            b = _mm256_or_si256(_mm256_slli_epi32(b,12), _mm256_srli_epi32(b,20)); \
            a = _mm256_add_epi32(a, b); \
            d = _mm256_xor_si256(d, a); \
