        QR8(s2,s6,s10,s14);
        QR8(s3,s7,s11,s15);
        QR8(s0,s5,s10,s15);
        QR8(s1,s6,s11,s12);
        QR8(s2,s7,s8,s13);
        QR8(s3,s4,s9,s14);
