    _mm256_storeu_si256((__m256i*)(dst_wordmajor+8), _mm256_add_epi32(s1,c1));
    _mm256_storeu_si256((__m256i*)(dst_wordmajor+16), _mm256_add_epi32(s2,c2));
    _mm256_storeu_si256((__m256i*)(dst_wordmajor+24), _mm256_add_epi32(s3,c3));
    _mm256_storeu_si256((__m256i*)(dst_wordmajor+32), _mm256_add_epi32(s4,k0));
    _mm256_storeu_si256((__m256i*)(dst_wordmajor+40), _mm256_add_epi32(s5,k1));
    _mm256_storeu_si256((__m256i*)(dst_wordmajor+48), _mm256_add_epi32(s6,k2));
