#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

void cc8(uint32_t *dst, uint32_t counter);

static inline uint32_t rotl(uint32_t x, int n) { return (x<<n) | (x>>(32-n)); }
static void qr(uint32_t s[16], int a,int b,int c,int d) {
    s[a]+=s[b]; s[d]^=s[a]; s[d]=rotl(s[d],16);
    s[c]+=s[d]; s[b]^=s[c]; s[b]=rotl(s[b],12);
    s[a]+=s[b]; s[d]^=s[a]; s[d]=rotl(s[d],8);
    s[c]+=s[d]; s[b]^=s[c]; s[b]=rotl(s[b],7);
}
static void scalar_block(uint32_t counter, uint32_t out[16]) {
    uint32_t s[16] = {
        0x61707865,0x3320646e,0x79622d32,0x6b206574,
        1,2,3,4,5,6,7,8,
        counter, 9,10,11
    };
    uint32_t init[16];
    memcpy(init, s, 64);
    for (int i = 0; i < 10; i++) {
        qr(s,0,4,8,12); qr(s,1,5,9,13); qr(s,2,6,10,14); qr(s,3,7,11,15);
        qr(s,0,5,10,15); qr(s,1,6,11,12); qr(s,2,7,8,13); qr(s,3,4,9,14);
    }
    for (int i = 0; i < 16; i++) out[i] = s[i] + init[i];
}

static double now() { struct timespec t; clock_gettime(CLOCK_MONOTONIC,&t); return t.tv_sec + t.tv_nsec*1e-9; }
static volatile uint64_t sink;

int main() {
    uint32_t *dst = aligned_alloc(64, 512);
    cc8(dst, 0);
    int bad = 0;
    for (int b = 0; b < 8; b++) {
        uint32_t ref[16];
        scalar_block(b, ref);
        for (int w = 0; w < 16; w++) {
            uint32_t got = dst[w*8 + b];
            if (got != ref[w]) {
                if (bad < 8) printf("mismatch block %d word %d got %08x ref %08x\n", b, w, got, ref[w]);
                bad++;
            }
        }
    }
    printf("mismatches %d\n", bad);
    if (bad) return 1;

    size_t n = 40UL<<20;
    size_t blocks = n / 512;
    uint32_t *buf = aligned_alloc(64, 512);
    /* warmup */
    for (size_t i = 0; i < blocks; i++) cc8(buf, (uint32_t)(i*8));
    sink += buf[0];
    int iters = 5;
    double t0 = now();
    for (int it = 0; it < iters; it++) {
        uint32_t ctr = 0;
        for (size_t i = 0; i < blocks; i++) { cc8(buf, ctr); ctr += 8; }
        sink += buf[it & 127];
    }
    double dt = now()-t0;
    printf("asm 8-wide compute-only 40MB x%d: %.3f ms avg, %.1f MB/s\n", iters, dt/iters*1000, (n/(dt/iters))/1e6);
    printf("sink %llu\n", (unsigned long long)sink);
    return 0;
}
