    return t.tv_sec + t.tv_nsec*1e-9;
}

/* checksum that forces a full read */
static uint64_t sum64(const uint8_t *p, size_t n) {
    uint64_t s = 0;
    const uint64_t *w = (const uint64_t*)p;
    size_t nw = n/8;
    for (size_t i = 0; i < nw; i += 8) {
        s += w[i]; s += w[i+1]; s += w[i+2]; s += w[i+3];
        s += w[i+4]; s += w[i+5]; s += w[i+6]; s += w[i+7];
    }
    return s;
}

int main() {
    size_t n = 40UL<<20;
    uint8_t *src = aligned_alloc(64, n);
    uint8_t *dst = aligned_alloc(64, n);
    /* fill with non-zero so zero-page opts don't apply */
    for (size_t i = 0; i < n; i += 4096) src[i] = (uint8_t)(i/4096);
    memset(dst, 1, n);
    uint64_t sink = 0;

    /* prefault both */
    sink += sum64(src, n) + sum64(dst, n);

    int iters = 20;
    double t0 = now();
    for (int i = 0; i < iters; i++) {
        memcpy(dst, src, n);
        sink += dst[i*64];
    }
