    printf("memcpy+touch1 40MB x%d: %.3f ms  copy-bw %.2f GB/s\n", iters, dt/iters*1000, (n/(dt/iters))/1e9);

    t0 = now();
    for (int i = 0; i < iters; i++) {
        memcpy(dst, src, n);
        sink += sum64(dst, n);
    }
    dt = now()-t0;
    printf("memcpy+fullsum 40MB x%d: %.3f ms (includes readback)\n", iters, dt/iters*1000);

    /* streaming xor: read src, write dst, full dependency */
    t0 = now();
    for (int i = 0; i < iters; i++) {
